/* ══════════════════════════════════════════════════════════════════
   实验 2 · Figure 8 交互重放
   ══════════════════════════════════════════════════════════════════ */
const F8=[
 {t:"(a) 任期 2：S1 是 Leader，把 index2 部分复制出去",
  leader:0, term:2,
  logs:[[1,2],[1,2],[1],[1],[1]],
  note:"S1 在任期 2 当选，接收客户端请求写下 <span class='chip'>index2 term2</span>，只复制到了 S2。<br>"+
       "2/5 个节点持有它，<strong>没有过半</strong>，当然不能提交。到这里一切正常。",
  hi:{idx:2,nodes:[0,1],kind:"warn"}},
 {t:"(b) 任期 3：S1 崩溃，S5 当选，在同一位置写下不同内容",
  leader:4, term:3, dead:[0],
  logs:[[1,2],[1,2],[1],[1],[1,3]],
  note:"S1 崩溃。S5 拿到 S3、S4 和自己的票当选任期 3（三者日志都是 <code>[1]</code>，S5 不比谁旧）。<br>"+
       "S5 在<strong>同一个 index2</strong> 上写下了 <span class='chip'>term3</span> 的<em>不同内容</em>，还没来得及复制出去就崩了。<br>"+
       "<span style='color:var(--ink-3)'>注意：现在 index2 上有两个互相冲突的版本，term2 和 term3。</span>",
  hi:{idx:2,nodes:[4],kind:"crit"}},
 {t:"(c) 任期 4：S1 重启并当选，把 term2 那条复制到过半",
  leader:0, term:4, dead:[4],
  logs:[[1,2,4],[1,2],[1,2],[1],[1,3]],
  note:"S5 崩溃，S1 重启后拿到 S1、S2、S3 的票当选任期 4（它的日志 <code>[1,2]</code> 比 S3 的 <code>[1]</code> 新）。<br>"+
       "S1 继续复制那条 <strong>term2</strong> 的日志，现在 S1、S2、S3 都有它 —— <strong>已经复制到过半（3/5）</strong>。<br>"+
       "S1 同时在自己 index3 写下了当前任期的 <span class='chip'>term4</span>，但还没复制出去。",
  hi:{idx:2,nodes:[0,1,2],kind:"key"}, decision:true},
 {t:"(d) 任期 5：S1 又崩了，S5 当选并覆盖 index2",
  leader:4, term:5, dead:[0],
  logs:[[1,2,4],[1,3],[1,3],[1,3],[1,3,3]],
  note:"S1 崩溃。S5 拿到 S2、S3、S4 的票当选任期 5 —— <strong>它凭什么能赢？</strong><br>"+
       "因为选举比的是 <code>(lastLogTerm, lastLogIndex)</code>，<strong>先比 term</strong>：<br>"+
       "S5 的最后一条是 <span class='chip'>term3</span>，S2/S3 的是 <span class='chip'>term2</span>。<strong>3 &gt; 2，S5 的日志更新</strong>，尽管它一样短。<br>"+
       "于是 S5 把 index2 上的 term2 <strong>全部覆盖成了 term3</strong>。",
  hi:{idx:2,nodes:[1,2,3],kind:"crit"}, overwrite:true},
 {t:"(e) 另一条路：S1 先把当前任期的日志复制到过半",
  leader:0, term:4,
  logs:[[1,2,4],[1,2,4],[1,2,4],[1],[1,3]],
  note:"回到 (c) 那一刻，假设 S1 在崩溃前先把<strong>当前任期</strong>的 <span class='chip'>index3 term4</span> 复制到了过半。<br>"+
       "此时 index3 满足提交条件（过半 + 当前任期），<strong>它被提交</strong>；由日志匹配性质，它之前的 index2 也<strong>随之被间接提交</strong>。<br>"+
       "现在 S5 <strong>再也赢不了选举了</strong>：它的最后一条是 (term3, index2)，而 S1/S2/S3 是 (term4, index3)，4 &gt; 3。<br>"+
       "<span style='color:var(--ok)'>已提交的数据从此安全。这就是提交限制想达到的效果。</span>",
  hi:{idx:3,nodes:[0,1,2],kind:"ok"}, safe:true}
];
let f8=0;
function draw2(){
  const P=F8[f8], naive=$("#c2naive").checked, svg=$("#sv2"); svg.innerHTML="";
  const cw=52, x0=104, maxLen=3;
  svg.appendChild(el("text",{x:14,y:18,fill:cv("--ink"),"font-size":13,"font-weight":700,"font-family":cv("--sans")},P.t));
  for(let i=1;i<=maxLen;i++) svg.appendChild(el("text",{x:x0+(i-1)*cw+cw/2-1,y:44,fill:cv("--ink-3"),
    "font-size":10,"text-anchor":"middle","font-family":cv("--mono")},"index "+i));
  P.logs.forEach((lg,i)=>{
    const y=54+i*36, dead=(P.dead||[]).includes(i), isL=P.leader===i;
    const label="S"+(i+1)+(isL?"  ★Leader":dead?"  ☠":"");
    drawLog(svg,label,lg,x0,y,cw,{bold:isL,
      labelColor:isL?cv("--ok"):dead?cv("--crit"):cv("--ink-2"),
      mark:P.hi&&P.hi.nodes.includes(i)?{[P.hi.idx]:P.hi.kind==="crit"?"del":P.hi.kind==="ok"?"new":"chk"}:{}});
  });
  const hx=x0+(P.hi.idx-1)*cw+cw/2-1;
  svg.appendChild(el("text",{x:hx,y:250,fill:cv(P.hi.kind==="crit"?"--crit":P.hi.kind==="ok"?"--ok":"--warn"),
    "font-size":10.5,"text-anchor":"middle","font-family":cv("--sans")},
    P.hi.nodes.length+"/5 个节点"));
  // 说明
  let h='<div class="note '+(P.safe?"ok":P.overwrite?"crit":"")+'" style="margin:0">';
  if(P.safe) h+='<div class="note-h"><span class="dot" style="background:var(--ok)"></span>安全的那条路</div>';
  if(P.overwrite) h+='<div class="note-h"><span class="dot" style="background:var(--crit)"></span>index2 上的 term2 被覆盖了</div>';
  h+='<p style="margin-bottom:0">'+P.note+'</p>';
  if(P.decision){
    h+= naive
      ? '<div class="note crit" style="margin:12px 0 0"><div class="note-h"><span class="dot" style="background:var(--crit)"></span>'+
        '你关掉了限制 —— 这里 Leader 会宣布 index2 已提交</div><p style="margin-bottom:0">'+
        '按朴素规则（只看"是否过半"），S1 此刻会把 <code>commitIndex</code> 推到 2，'+
        '把 index2 标记为<strong>已提交</strong>，并<strong>回复客户端"成功"</strong>。<br>'+
        '<strong>记住这一刻。</strong>点「下一阶段」看它的下场。</p></div>'
      : '<div class="note ok" style="margin:12px 0 0"><div class="note-h"><span class="dot" style="background:var(--ok)"></span>'+
        'Raft 在这里踩了刹车</div><p style="margin-bottom:0">'+
        'index2 已经复制到过半（3/5），但它的 term 是 2，而当前任期是 4 —— '+
        '<strong>不满足 <code>log[N].term == currentTerm</code>，所以不能提交</strong>。<br>'+
        'S1 只能把它留在"已复制未提交"状态，<em>不向客户端承诺任何东西</em>。<br>'+
        '<span style="color:var(--ink-3)">把上面那个开关打开，再走一遍，看不踩刹车会怎样。</span></p></div>';
  }
  if(P.overwrite){
    h+= naive
      ? '<div class="note crit" style="margin:12px 0 0"><div class="note-h"><span class="dot" style="background:var(--crit)"></span>'+
        '★ 安全性破产：已经告诉客户端"成功"的数据凭空消失了</div><p style="margin-bottom:0">'+
        '上一步你关掉了限制，S1 已经把 index2 标为已提交并回复了客户端成功。<br>'+
        '现在 S5 当选，把 S2、S3、S4 上的那条 term2 <strong>全部改写成了 term3</strong>。<br>'+
        '<strong>结果：客户端收到过"成功"的那条数据，在集群里已经不存在了。</strong><br>'+
        '更糟的是 —— 如果某个节点已经把 term2 那条命令 apply 到状态机，而另一个节点 apply 的是 term3 那条，'+
        '<strong>状态机安全性也被破坏</strong>：同一个 index 上不同节点执行了不同的命令，副本从此分叉。<br>'+
        '<em>这就是为什么必须有那条限制。</em></p></div>'
      : '<div class="note" style="margin:12px 0 0"><div class="note-h"><span class="dot" style="background:var(--s1)"></span>'+
        '覆盖发生了，但没有造成任何伤害</div><p style="margin-bottom:0">'+
        'S5 确实覆盖掉了 S2/S3 上那条 term2 的日志。但因为 Raft <strong>从未把它宣布为已提交</strong>，'+
        '客户端也从未收到"成功"，所以丢掉它<u>不违反任何承诺</u>。<br>'+
        '<strong>Raft 的高明之处就在这里</strong>：它没有去阻止覆盖（那需要改选举规则，代价大得多），'+
        '而是<em>确保被覆盖的东西从来没被承诺过</em>。<br>'+
        '<span style="color:var(--ink-3)">把开关打开再走一遍，看同样这一步会造成什么后果。</span></p></div>';
  }
  h+='</div>';
  $("#o2").innerHTML=h;
  $("#b2prev").disabled=f8===0; $("#b2next").disabled=f8===F8.length-1;
}
$("#b2next").onclick=()=>{if(f8<F8.length-1){f8++;draw2();}};
$("#b2prev").onclick=()=>{if(f8>0){f8--;draw2();}};
$("#b2reset").onclick=()=>{f8=0;draw2();};
$("#c2naive").onchange=draw2;
draw2();

/* ══════════════════════════════════════════════════════════════════
   实验 3 · 回退策略对照
   ══════════════════════════════════════════════════════════════════ */
function draw3(){
  const g=+$("#r3g").value, t=+$("#r3t").value, d=+$("#r3d").value;
  $("#l3g").textContent=g; $("#l3t").textContent=t; $("#l3d").textContent=d+" ms";
  const naive=g+1, fast=Math.min(t,g)+1;
  const svg=$("#sv3"); svg.innerHTML="";
  const L=140,R=650,TOP=32,BH=30,GAP=44;
  const mx=Math.max(naive,fast);
  [["朴素回退（每次 −1）",naive,"--crit"],["快速回退（按任期跳）",fast,"--ok"]].forEach((row,i)=>{
    const y=TOP+i*(BH+GAP), w=Math.max(row[1]/mx*(R-L),4);
    svg.appendChild(el("text",{x:L-12,y:y+BH/2+4,fill:cv("--ink-2"),"font-size":11.5,"text-anchor":"end","font-family":cv("--sans")},row[0]));
    svg.appendChild(el("rect",{x:L,y:y,width:w,height:BH,rx:4,fill:cv(row[2])}));
    svg.appendChild(el("text",{x:L+w+10,y:y+BH/2+4,fill:cv("--ink"),"font-size":11.5,"font-family":cv("--sans")},
      row[1]+" 轮 RPC　·　约 "+(row[1]*2*d)+" ms"));
  });
  svg.appendChild(el("text",{x:R,y:TOP+2*(BH+GAP)+2,fill:cv("--ink-3"),"font-size":10.5,"text-anchor":"end","font-family":cv("--sans")},
    "追平一个落后 follower 所需的 RPC 轮数（每轮一个网络往返）"));
  $("#st3").innerHTML=
    '<div class="stat"><div class="k">朴素回退</div><div class="v" style="color:var(--crit)">'+naive+'</div><div class="u">轮 · '+(naive*2*d)+' ms</div></div>'+
    '<div class="stat"><div class="k">快速回退</div><div class="v" style="color:var(--ok)">'+fast+'</div><div class="u">轮 · '+(fast*2*d)+' ms</div></div>'+
    '<div class="stat"><div class="k">加速比</div><div class="v">'+(naive/fast).toFixed(1)+'×</div><div class="u">RPC 轮数之比</div></div>'+
    '<div class="stat"><div class="k">节省时间</div><div class="v">'+((naive-fast)*2*d)+'</div><div class="u">毫秒</div></div>';
  $("#o3").innerHTML='<div class="note" style="margin:0"><div class="note-h">'+
    '<span class="dot" style="background:var(--s1)"></span>为什么按任期跳是对的</div>'+
    '<p style="margin-bottom:0">一个任期内的日志是同一个 Leader 连续写下的，<strong>要么整段都和当前 Leader 一致，要么整段都不一致</strong>'+
    '（由日志匹配性质：只要有一个位置的 term 相同，前面就全相同）。<br>'+
    '所以在一个冲突任期内部逐条回退是<em>纯粹的浪费</em> —— 直接跳到该任期的第一条即可。<br>'+
    '真实系统里日志常有几万条却只跨越几个任期，所以这个优化通常把几万轮 RPC 降到个位数。<br>'+
    '<span style="color:var(--ink-3)">把「落后条数」拖到 200、「任期数」保持 3，看两条柱子的差距。</span></p></div>';
}
["r3g","r3t","r3d"].forEach(i=>$("#"+i).oninput=draw3);
draw3();
})();
</script>
</body>
</html>
